import{_ as r,o as n,c as t,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"3D Printer Card","description":"Kompakte Home-Assistant-Card für Klipper und Moonraker mit Profilen, Kamera und Temperaturgraphen.","frontmatter":{"title":"3D Printer Card","description":"Kompakte Home-Assistant-Card für Klipper und Moonraker mit Profilen, Kamera und Temperaturgraphen."},"headers":[],"relativePath":"projects/3d-printer-card/index.md","filePath":"projects/3d-printer-card/index.md","lastUpdated":1795791313000}'),i={name:"projects/3d-printer-card/index.md"};function o(s,e,d,l,u,c){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="_3d-printer-card" tabindex="-1">3D Printer Card <a class="header-anchor" href="#_3d-printer-card" aria-label="Permalink to &quot;3D Printer Card&quot;">​</a></h1><p><a href="/en/projects/3d-printer-card/">English</a> · <a href="/fr/projects/3d-printer-card/">Français</a></p><p><strong>Version 0.1.6. Funktioniert nur mit Klipper und Moonraker.</strong> Die <a href="https://github.com/marcolivierarsenault/moonraker-home-assistant" target="_blank" rel="noreferrer">Moonraker-Integration</a> muss installiert und für jeden Drucker eingerichtet sein. Die Card verwendet deren HA-Entitäten ohne eigene Anmeldung oder zusätzliche Druckerverbindung.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=3d-printer-card&amp;category=plugin" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="In HACS öffnen"></a></p><ol><li>Einstellungen sichern. Die <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=marcolivierarsenault&amp;repository=moonraker-home-assistant&amp;category=integration" target="_blank" rel="noreferrer">Moonraker-Integration in HACS</a> installieren und konfigurieren.</li><li><code>https://github.com/rockbaer2007/3d-printer-card</code> in HACS als benutzerdefiniertes <strong>Dashboard</strong>-Repository hinzufügen und herunterladen. Noch nicht im allgemeinen HACS-Katalog gelistet.</li><li>Ressource <code>/hacsfiles/3d-printer-card/3d-printer-card.js</code> als <strong>JavaScript-Modul</strong> prüfen und Browser neu laden. Eine bisherige lokale Ressource ersetzen; nicht beide gleichzeitig laden.</li><li>Im Dashboard <strong>3D Printer Card</strong> hinzufügen. Der technische Typ bleibt <code>custom:moonraker-display-card</code>.</li></ol><p>Manuell: JS-Datei aus dem Release nach <code>/config/www/3d-printer-card/</code> kopieren und <code>/local/3d-printer-card/3d-printer-card.js?v=0.1.6</code> als JavaScript-Modul registrieren. Kein HA-Neustart nötig. Alle Entitäten der Beispielvorlage durch die eigenen ersetzen.</p><h2 id="anzeige-und-profile" tabindex="-1">Anzeige und Profile <a class="header-anchor" href="#anzeige-und-profile" aria-label="Permalink to &quot;Anzeige und Profile&quot;">​</a></h2><ul><li>Status, Dateiname, Fortschritt, Druckdauer, Restzeit, geschätzte Gesamtdauer, Fertigstellung und Schichten; außerdem Geschwindigkeit, Lüfter und Meldungen.</li><li>Düse und Bett jeweils Ist/Soll in einem Graphen; Board- und Padtemperatur jeweils Ist im zweiten Graphen. Verläufe benötigen die entsprechenden Entitäten im HA-Recorder.</li><li>Livekamera rechts mit ungefähr einem Drittel der Breite und optionaler Modellvorschau. Auf schmalen Displays untereinander.</li><li>Kompakte Wertefelder, flache Graphen, Standardbreite 24 Spalten, automatische Höhe. Eine HA-Abschnittsansicht verwenden; Panelansichten erzwingen volle Breite.</li><li>Bis zu 20 Druckerprofile mit eigenen Entitäten und Kameras.</li></ul><p>Im visuellen Editor <strong>Profil hinzufügen</strong> oder <strong>Profil bearbeiten</strong> öffnen. Über <strong>Drucker erkennen</strong> den <code>current_print_state</code>-Sensor wählen; das Entitätspräfix wird erkannt. Kameras und abweichende Zuordnungen über die native HA-Entitätensuche auswählen. <strong>Profil übernehmen</strong>, danach im äußeren Editor <strong>Speichern</strong>. Der Editor ist derzeit Deutsch; Doku DE/EN/FR. Bestehende Profile bleiben kompatibel.</p><h2 id="druckabbruch-und-prufung" tabindex="-1">Druckabbruch und Prüfung <a class="header-anchor" href="#druckabbruch-und-prufung" aria-label="Permalink to &quot;Druckabbruch und Prüfung&quot;">​</a></h2><p>Einzige Aktion: <strong>Druck abbrechen</strong>, über den vorhandenen HA-Button bei aktivem/pausiertem Druck und betriebsbereitem Drucker. Bestätigung und erneute Zustandsprüfung sind erforderlich. Profilwechsel senden keine Druckerbefehle. Kein Filamentverbrauch und keine Gesamtstatistik.</p><p>Mit echten Entitäten unter HA 2026.11.3 geprüft: Anzeige, Kamera, Graphen und Profilbearbeitung bei erhaltenen Einstellungen. Zusätzlich 16 automatisierte Tests und Browserprüfungen mit 390, 800 und 1500 Pixeln ohne Überläufe oder ungewollte Dienstaufrufe. Kein echter laufender Druck wurde im Test abgebrochen.</p><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><ul><li><a href="https://github.com/rockbaer2007/3d-printer-card" target="_blank" rel="noreferrer">GitHub und vollständige Anleitung</a></li><li><a href="https://github.com/rockbaer2007/3d-printer-card/releases/tag/v0.1.6" target="_blank" rel="noreferrer">Release 0.1.6 mit ZIP und JavaScript</a></li><li><a href="https://github.com/rockbaer2007/3d-printer-card/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">Changelog</a></li></ul><p>MIT-Lizenz. Eigenständiges Frontend-Projekt, getrennt von der Moonraker-Integration.</p>',16)])])}const g=r(i,[["render",o]]);export{p as __pageData,g as default};
